#include "cinderwatch/ioc/ioc.h"
namespace cinderwatch::ioc{using namespace core;static List ctx(const std::string&s,List f){auto l=lower(s);if(l.find("allow")!=std::string::npos)return List::Allow;if(l.find("block")!=std::string::npos||l.find("deny")!=std::string::npos)return List::Block;return f;}Result<Indicator> parse_token(const std::string&t,List l,const std::string&s,size_t line){auto x=trim(strip_quotes(t));if(x.empty())return Status::error(Code::Invalid,"empty indicator");Indicator i;i.raw=x;i.list=l;i.source=s;i.line=line;auto c=parse_cidr(x);if(c){i.type=c.value().prefix==32&&x.find('/')==std::string::npos?Type::IPv4:Type::CIDR;i.cidr=c.value();i.ip=c.value().net;i.norm=c.value().text();return i;}auto h=detect_hash(x);if(h!=HashKind::Unknown){i.type=Type::Hash;i.hash=h;i.norm=lower(x);return i;}if(url_like(x)){i.type=Type::URL;i.norm=norm_url(x);return i;}if(domain_like(x)){i.type=Type::Domain;i.norm=norm_domain(x);return i;}return Status::error(Code::Malformed,"unknown indicator");}Store load_text(const std::string&t,const std::string&s){Store st;List l=List::Observe;size_t no=0;for(auto&r:lines(t)){no++;auto x=trim(r);if(x.empty())continue;if(x[0]=='#'||x[0]==';'){l=ctx(x,l);continue;}for(auto&w:words(x)){auto ind=parse_token(w,l,s,no);if(ind)st.indicators.push_back(ind.value());}}return st;}Store load_file(const std::string&p){auto t=read_text(p);if(!t){Store s;s.diagnostics.push_back({Severity::High,"ioc.file",t.st.msg,{p,1,1,0}});return s;}return load_text(t.value(),p);}static void add(std::vector<Match>&o,const Indicator&i,const std::string&a,const std::string&f,const std::string&v){Severity s=i.list==List::Block?Severity::High:i.list==List::Allow?Severity::Info:i.sev;o.push_back({i,a,f,v,"indicator matched "+f,s});}std::vector<Match> match_text(const Store&s,const std::string&name,const std::string&t){std::vector<Match>o;auto ws=words(t);std::set<std::string>norm;for(auto&w:ws){norm.insert(lower(w));if(domain_like(w))norm.insert(norm_domain(w));if(url_like(w))norm.insert(norm_url(w));}for(auto&i:s.indicators){if(i.type==Type::Domain||i.type==Type::URL||i.type==Type::Hash){if(norm.count(i.norm))add(o,i,name,"text",i.norm);}else for(auto&w:ws){auto ip=parse_ipv4(w);if(ip&&((i.type==Type::IPv4&&ip.value().v==i.ip.v)||(i.type==Type::CIDR&&i.cidr.contains(ip.value()))))add(o,i,name,"ip",w);}}return o;}std::vector<Match> match_packet(const Store&s,const packet::PacketSummary&p){std::vector<Match>o;for(auto&i:s.indicators){if(i.type==Type::IPv4){if(p.src.v==i.ip.v)add(o,i,"packet","src",p.src.text());if(p.dst.v==i.ip.v)add(o,i,"packet","dst",p.dst.text());}if(i.type==Type::CIDR){if(i.cidr.contains(p.src))add(o,i,"packet","src",p.src.text());if(i.cidr.contains(p.dst))add(o,i,"packet","dst",p.dst.text());}if(i.type==Type::Domain)for(auto&d:p.dns)if(norm_domain(d)==i.norm)add(o,i,"packet","dns",d);}return o;}std::vector<Match> match_pcap(const Store&s,const packet::Analysis&a){std::vector<Match>o;for(auto&p:a.packets){auto m=match_packet(s,p);o.insert(o.end(),m.begin(),m.end());}return o;}std::string text(const std::vector<Match>&m){std::ostringstream o;if(m.empty())o<<"No indicator matches\n";for(auto&x:m)o<<severity_name(x.sev)<<" "<<x.field<<" "<<x.value<<" -> "<<x.ind.raw<<"\n";return o.str();}std::string json(const std::vector<Match>&m){std::ostringstream o;o<<"[";bool f=true;for(auto&x:m){if(!f)o<<",";f=false;o<<"{\"severity\":\""<<severity_name(x.sev)<<"\",\"field\":\""<<json_escape(x.field)<<"\",\"value\":\""<<json_escape(x.value)<<"\"}";}o<<"]";return o.str();}}
